using System;using System.IO;using System.Linq;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro{public static class LatchInProcess{
static IZDoc D(object x){return x is IZDoc?(IZDoc)x:(IZDoc)Marshal.GetObjectForIUnknown(new IntPtr(Convert.ToInt64(x)));}
public static int Run(string folder){var j=new JavaScriptSerializer{MaxJsonLength=64000000};var r=new Dictionary<string,object>();try{var q=(Dictionary<string,object>)j.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json")));if(System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(q["expected_pid"]))throw new Exception("Host changed");dynamic l=Marshal.GetActiveObject("IronCAD.Application");var a=(IZBaseApp)l.ZIronCADApp;if(!a.ApiVersion.StartsWith("29."))throw new Exception("2027 required");var docs=((Array)a.GetAllOpenDocs()).Cast<object>().Select(D).ToArray();r["documents"]=docs.Select(d=>new{path=d.Name,guid=d.FileGUID,modified=d.Modified}).ToArray();string source=(string)q["source"],target=(string)q["snapshot"];if(File.Exists(target))throw new Exception("Snapshot exists");var d0=docs.Single(d=>String.Equals(d.Name,source,StringComparison.OrdinalIgnoreCase));string guid=d0.FileGUID;bool modified=d0.Modified;var s=(IZSceneDoc)d0;if(s.ParameterMgr.Count!=34)throw new Exception("Expected R002");s.SaveAsCopy(target,eZLinksSaveOptions.Z_LINKS_COPY_ALL,false);if(d0.Name!=source||d0.FileGUID!=guid||d0.Modified!=modified)throw new Exception("Source state changed");r["parameters"]=Enumerable.Range(0,s.ParameterMgr.Count).Select(i=>s.ParameterMgr.GetParameter(i)).Select(p=>new{name=p.Name,expression=p.Expression,value=p.Value,notes=p.Notes}).ToArray();r["source_preserved"]=true;r["snapshot"]=target;r["passed"]=true;}catch(Exception e){r["passed"]=false;r["error"]=e.ToString();}File.WriteAllText(Path.Combine(folder,"result.json"),j.Serialize(r));return (bool)r["passed"]?0:1;}}}
